// TRANSPORT NORMALIZATION ONLY. No SQL, no LLM, no grounding.
// Extract the user question from the webhook body and build the T2S request.
// Propagate the n8n execution id as x-request-id for end-to-end correlation.
const raw = $input.first().json;
const body = (raw && raw.body) ? raw.body : raw;
const question = (body && body.question != null) ? String(body.question) : '';
const locale = (body && body.locale) ? body.locale : 'auto';
const evidence = (body && Array.isArray(body.evidence)) ? body.evidence : undefined;
const payload = { question, locale };
if (evidence) payload.evidence = evidence;
return [{ json: { t2s_request: payload, x_request_id: 'n8n-' + $execution.id } }];

// TRANSPORT NORMALIZATION ONLY. Preserve T2S decision semantics verbatim.
// Never fabricate an answer or SQL; abstain stays abstain; errors stay errors.
const item = $input.first().json;
const httpStatus = (item && item.statusCode != null) ? item.statusCode : 200;
const t2s = (item && item.body != null) ? item.body : item;
const isErr = httpStatus >= 400;
return [{ json: {
  n8n_execution_id: $execution.id,
  http_status: httpStatus,
  t2s_request_id: t2s && t2s.request_id != null ? t2s.request_id : null,
  t2s_run_id: t2s && t2s.run_id != null ? t2s.run_id : null,
  t2s_trace_id: t2s && t2s.trace_id != null ? t2s.trace_id : null,
  status: t2s && t2s.status != null ? t2s.status : (isErr ? 'error' : null),
  decision: t2s && t2s.decision != null ? t2s.decision : null,
  sql: t2s && t2s.sql != null ? t2s.sql : null,
  answer: t2s && t2s.answer != null ? t2s.answer : null,
  explanation: t2s && t2s.explanation != null ? t2s.explanation : null,
  warnings: t2s && Array.isArray(t2s.warnings) ? t2s.warnings : [],
  error: isErr ? (t2s && (t2s.error || t2s.detail) ? (t2s.error || t2s.detail) : 'request_error') : null
}}];
